 .memory-flow{position:relative;display:flex;justify-content:center;align-items:center;gap:19px;padding:24px 0 30px;min-width:0}.memory-label{display:flex;align-items:center;gap:8px;font-size:8px;font-weight:600;letter-spacing:.08em;color:#7b8b6f}.memory-label>span{font-size:21px;color:#7f9866}.memory-chips{display:flex;gap:6px}.memory-chips>span{padding:5px 9px;border:1px solid #e0e6d8;border-radius:4px;font-size:9px;color:#819172;background:#f5f7f0}.flow-arrow{position:absolute;bottom:3px;font-size:18px;color:#9eae8b}
 .output-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;align-items:stretch}.output-app{display:flex;flex-direction:column;min-width:0;border:1px solid #dce3d6;border-radius:8px;background:#fff;overflow:hidden;box-shadow:0 7px 17px #43583006}.app-title{display:flex;align-items:center;gap:10px;padding:16px 14px;border-bottom:1px solid #e5e9e0;min-height:66px}.app-title :global(.service-logo){width:25px;height:29px}.app-title>div{min-width:0;flex:1}.app-title strong{display:block;font-size:12px;font-weight:600;line-height:1.4}.app-title>div>span{display:block;font-size:8px;color:#94a088;margin-top:3px}.app-state{display:inline-flex;align-items:center;gap:4px;font-size:8px;color:#929c87;background:#f2f4ee;padding:4px 7px;border-radius:4px;white-space:nowrap}.app-state.ready{background:#e8f1df;color:#61834d}.app-menu{display:flex;align-items:center;gap:12px;padding:9px 13px;font-size:7px;color:#97a18c;border-bottom:1px solid #e8ece2;background:#fafbf8;min-height:29px}.menu-end{margin-left:auto;font-size:7px;white-space:nowrap}
 .slides-editor{display:grid;grid-template-columns:46px minmax(0,1fr);gap:11px;padding:17px 12px 16px 8px;background:#f2f4ef;flex:1;min-height:415px}.slide-filmstrip{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:7px}.slide-filmstrip button{width:100%;display:flex;align-items:center;gap:4px;padding:0;opacity:.45}.slide-filmstrip button.filled,.slide-filmstrip button.selected{opacity:1}.slide-filmstrip button>span:first-child{font-size:6px;color:#9aab8e;min-width:7px}.thumb-paper{display:flex;flex-direction:column;justify-content:center;gap:4px;border:1px solid #dfe5d7;border-radius:2px;width:29px;height:21px;padding:5px;background:white}.selected .thumb-paper{border:1px solid #8aa66f;background:#edf2e5}.thumb-paper i{display:block;height:2px;background:#dce5cf;width:100%}.thumb-paper i:last-child{width:65%}.slide-workspace{min-width:0;padding-top:2px}.slide-position{display:block;font-size:7px;letter-spacing:.09em;color:#a1ad96;margin:0 0 12px 1px}.demo-slide{position:relative;aspect-ratio:1.45;background:#fffef9;border:1px solid #e1e6d9;border-radius:3px;padding:17px 16px 22px;overflow:hidden}.demo-slide.cover{background:#35553f;color:#fffef7;border-color:#35553f}.slide-kind{display:block;font-size:6px;letter-spacing:.09em;color:#92a281}.cover .slide-kind{color:#bacaa6}.demo-slide h3{font-size:17px;line-height:1.35;font-weight:500;letter-spacing:-.045em;margin:15px 0 12px}.demo-slide>p{font-size:8px;line-height:1.7;white-space:pre-wrap;margin:0;color:#809170}.cover>p{color:#d1dec2}.demo-slide>footer{position:absolute;bottom:9px;left:16px;right:16px;display:flex;justify-content:space-between;font-size:5px;letter-spacing:.04em;color:#a2b18f}.cover>footer{color:#b5c6a0}.slide-notes{margin-top:19px;border-top:1px solid #dce3d4;padding-top:13px}.slide-notes strong{display:block;font-size:11px;font-weight:550;color:#688059}.slide-notes>span{display:block;font-size:9px;color:#94a087;line-height:1.8;margin-top:7px}.waiting-content{padding-top:18px}.waiting-symbol{display:block;font-size:28px;color:#b6c3a4}.waiting-content>p{font-size:10px;line-height:1.7;color:#8c9e7e;margin:9px 0 17px}.skeleton-line{height:4px;border-radius:1px;background:#e7ecdf;margin:9px 0;width:100%}.skeleton-line.short{width:65%}
 .docs-editor{position:relative;background:#f4f5f2;flex:1;padding:23px 18px 15px;min-height:415px}.ruler{position:absolute;top:8px;left:18px;right:18px;height:6px;border-bottom:1px solid #e0e5d9;background:repeating-linear-gradient(90deg,transparent,transparent 14px,#dfe5d7 14px,#dfe5d7 15px)}.summary-page{position:relative;min-height:371px;padding:26px 24px 33px;background:#fffefc;box-shadow:0 1px 5px #586f3010;border:1px solid #e7e9e0}.document-kicker{display:block;font-size:5px;letter-spacing:.07em;color:#99a18e}.summary-page h3{font-size:19px;font-weight:500;line-height:1.4;letter-spacing:-.045em;margin:17px 0 13px}.document-rule{height:1px;background:#e0e6d7;margin-bottom:17px}.summary-text{font-size:8px;line-height:1.8;white-space:pre-wrap;margin:0;color:#7b8871}.page-number{position:absolute;bottom:13px;left:50%;font-size:6px;color:#b4bca9}.document-skeleton{padding-top:10px}.document-skeleton .skeleton-line{height:3px;margin-block:14px}.document-skeleton .skeleton-line:nth-child(4){margin-top:27px}.waiting-note{font-size:9px;line-height:1.9;color:#a2ad96;margin-top:24px}
 .blog-menu strong{font-size:6px;font-weight:500;letter-spacing:.06em;color:#849b72}.blog-editor{flex:1;min-height:415px;background:#fffefc}.blog-cover{position:relative;overflow:hidden;background:#e7efda;min-height:108px;padding:19px 20px;color:#577045}.blog-cover>span{display:block;font-size:5px;letter-spacing:.1em;color:#8ca076}.blog-cover>strong{display:block;font-size:19px;font-weight:500;line-height:1.35;letter-spacing:-.045em;margin-top:12px;position:relative;z-index:1}.cover-lines{position:absolute;right:19px;bottom:19px;display:flex;gap:4px;transform:rotate(-16deg)}.cover-lines i{width:14px;height:47px;background:#cedcb9;border:1px solid #c5d5ac}.cover-lines i:nth-child(2){height:58px;margin-top:-11px}.cover-lines i:nth-child(3){height:70px;margin-top:-23px}.blog-copy{padding:17px 22px 21px}.blog-category{font-size:5px;letter-spacing:.1em;color:#92a27f}.blog-copy h3{font-size:17px;line-height:1.35;font-weight:500;letter-spacing:-.04em;margin:9px 0 10px}.blog-byline{display:flex;align-items:center;gap:6px;font-size:6px;color:#9da88f;margin-bottom:14px}.blog-byline>span{width:17px;height:17px;background:#eff3e8;border-radius:50%;display:grid;place-items:center;color:#81966d;font-size:7px}.blog-text{font-size:8px;line-height:1.85;white-space:pre-wrap;margin:0;color:#819074}.blog-tags{font-size:7px;line-height:1.8;margin-top:15px;color:#91a279}.app-footer{display:flex;align-items:center;gap:7px;min-height:34px;padding:9px 12px;font-size:7px;color:#9ba78e;border-top:1px solid #e4e9de;background:#fffef9}.state-dot{height:4px;width:4px;border-radius:50%;background:#c8d3bc;flex:none}.state-dot.done{background:#86a465}
 .writing-caret{display:inline-block;height:.95em;width:1px;background:#829f65;margin-left:2px;vertical-align:-.1em;animation:blink 1s steps(1) infinite}.writing-caret.invisible{visibility:hidden}.workflow-demo[data-playing='false'] .writing-caret{animation:none}.playback{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:18px}.playback-status{display:flex;align-items:center;gap:8px;min-width:0}.playback-status>p{font-size:11px;color:#667d56;margin:0;line-height:1.7}.play-indicator{width:5px;height:5px;border-radius:50%;background:#b0be9c;flex:none}.play-indicator.complete{background:#82a262}.demo-badge{font-size:6px;letter-spacing:.07em;color:#a0ab94;margin-left:6px;padding:4px 6px;border:1px solid #e1e7d8;border-radius:3px;white-space:nowrap}.playback-controls{display:flex;align-items:center;gap:13px;min-width:0}.playback-controls>button{font-size:10px;color:#768a65;display:flex;align-items:center;gap:6px;padding:6px 3px;white-space:nowrap}.playback-controls>button>span{font-size:15px}.demo-progress{width:145px;min-width:40px;height:17px;padding:0;border:0;box-shadow:none;background:transparent;accent-color:#7e9766;cursor:pointer}.phase-track{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;list-style:none;padding:0;margin:17px 0 0}.phase-track>li{border-top:2px solid #e5eadf;padding-top:9px;font-size:9px;color:#a5af9a;line-height:1.8}.phase-track>li>span{font-size:7px;margin-right:8px;color:#b0bba3}.phase-track>li.reached{border-color:#98b07b;color:#6e865b}.phase-track>li.reached>span{color:#8ca278}.demo-disclosure{font-size:9px;line-height:1.8;text-align:center;color:#97a38a;margin:20px 0 0}
 @keyframes blink{50%{opacity:0}}
